#!/usr/bin/env bash
# ops/batch_p07b_channels_and_reconnect.sh
#
# Batch B of P0.7 - built on top of Batch A (batch_p07a_core_backend.sh,
# already delivered/applied). Three independent pieces, applied in order,
# each one aborting cleanly (set -euo pipefail) before touching the next if
# anything looks wrong:
#
#   1. gateway/: F19 (POST /sessions now accepts/stores tenant_id/
#      channel_account_id/engine; meta.json persistence + rehydrate restore;
#      WAL entries tagged with `engine`; forwarder.js skips legacy webhook
#      delivery for engine=ai_core sessions) and F20 (new
#      POST /sessions/:id/reconnect route + reconnectSession(), including the
#      fencingToken re-acquisition bug my own test caught and fixed - see
#      docs/P0_FINDINGS.md F19/F20 for the full story). ONLY the 10 specific
#      files this session actually touched - nothing else in gateway/ is
#      re-shipped.
#      Self-verified: 140/140 real tests (real Redis, real FakeWaDriver, no
#      mocked transport), hunt_gate clean on every file in this list.
#
#   2. core/: full tree, superseding Batch A - adds the P0.7 channel-
#      lifecycle routes (GET /v1/me, GET /v1/channels,
#      POST /v1/channels/whatsapp, GET /v1/channels/{id},
#      GET /v1/channels/{id}/qr, POST /v1/channels/{id}/reconnect) plus their
#      own test suite (test_routes_channels.py, 22 tests) and the repos.py/
#      testsupport.py additions they needed.
#      Self-verified: 265/265 real tests (real Postgres 16+PostGIS+pgvector,
#      real Redis, real stub gateway HTTP server - no mocks), ruff clean,
#      mypy --strict clean (21 files), import-linter clean (psycopg still
#      confined to app.db only), hunt_gate clean on every changed file.
#      GET /v1/channels/{id}/delivery-stats is deliberately NOT built (D-29 -
#      its gateway dependency does not exist in the real code).
#
#   3. docs/P0_FINDINGS.md and docs/P0_DEVIATIONS.md: F19/F20/F21 and
#      D-29/D-30/D-31 respectively - delivered as a GUARDED APPEND (grep for
#      the exact last line each file had before this session's additions;
#      abort if it is not found verbatim, rather than risk silently
#      overwriting or duplicating content this sandbox never saw on your real
#      VPS copy).
#
# This script NEVER runs `git commit`. Review the diff, then commit yourself
# (Gate A) - exactly like every batch before it.
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || true)"
if [ -z "$REPO_ROOT" ]; then
  echo "error: not inside a git repository. cd into the sharwa_ai repo root first." >&2
  exit 1
fi
if [ ! -f "$REPO_ROOT/docker-compose.yml" ] || [ ! -d "$REPO_ROOT/gateway" ] || [ ! -d "$REPO_ROOT/core" ]; then
  echo "error: $REPO_ROOT doesn't look like the sharwa_ai repo root, or Batch A hasn't been applied yet (no core/)." >&2
  exit 1
fi
cd "$REPO_ROOT"

echo "== [1/3] gateway/: F19 (engine/tenant_id/channel_account_id metadata) + F20 (reconnect route) =="
GATEWAY_FILES_TO_TOUCH=(
  "gateway/src/sessions.js"
  "gateway/src/forwarder.js"
  "gateway/src/index.js"
  "gateway/src/__tests__/forwarder.test.js"
  "gateway/src/__tests__/engine_tagging.test.js"
  "gateway/src/__tests__/session_metadata.test.js"
  "gateway/src/__tests__/session_meta_rehydrate.test.js"
  "gateway/src/__tests__/p07_sessions_metadata_route.test.js"
  "gateway/src/__tests__/reconnect_session.test.js"
  "gateway/src/__tests__/p07_reconnect_route.test.js"
)
for f in "${GATEWAY_FILES_TO_TOUCH[@]}"; do
  if [ -f "$f" ]; then
    backup="${f}.bak-$(date +%Y%m%d%H%M%S)"
    cp "$f" "$backup"
    echo "  backed up existing $f -> $backup"
  fi
done
GATEWAY_TARBALL_B64=''
echo "$GATEWAY_TARBALL_B64" | base64 -d | tar xzf - -C "$REPO_ROOT"
echo "  gateway/ files written: ${#GATEWAY_FILES_TO_TOUCH[@]}"

echo
echo "== [2/3] core/: full tree (supersedes Batch A) =="
if [ -d core ] && [ -n "$(ls -A core 2>/dev/null)" ]; then
  backup="core.bak-$(date +%Y%m%d%H%M%S)"
  echo "  core/ already exists and is non-empty - backing it up to $backup/ first (nothing is deleted)."
  cp -r core "$backup"
fi
CORE_TARBALL_B64=''
echo "$CORE_TARBALL_B64" | base64 -d | tar xzf - -C "$REPO_ROOT"
echo "  core/ written. File count: $(find core -type f | wc -l)"

echo
echo "== [3/3] docs/: guarded append of F19-F21 / D-29-D-31 =="

append_guarded() {
  local file="$1" anchor="$2" newblock_b64="$3" label="$4"
  if [ ! -f "$file" ]; then
    echo "  error: $file does not exist - cannot guard-append. Skipping (apply by hand)." >&2
    return 1
  fi
  if ! grep -qF "$anchor" "$file"; then
    echo "  error: $label - the expected anchor text (end of the last entry this" >&2
    echo "         session knew about) was not found verbatim in your real $file." >&2
    echo "         Your file has diverged from this sandbox's reconstruction -" >&2
    echo "         nothing was written. Merge the new section by hand; it is saved" >&2
    echo "         at: /tmp/$(basename "$file").p07b_new_section for you to paste in." >&2
    echo "$newblock_b64" | base64 -d > "/tmp/$(basename "$file").p07b_new_section"
    return 1
  fi
  if grep -qF "## F19" "$file" 2>/dev/null || grep -qF "## D-29" "$file" 2>/dev/null; then
    echo "  skipping $file - it already contains this batch's new sections (already applied?)." >&2
    return 0
  fi
  echo "$newblock_b64" | base64 -d >> "$file"
  echo "  appended to $file"
}

FINDINGS_NEW_B64=''
DEVIATIONS_NEW_B64=''
FINDINGS_ANCHOR='**نطاق الإصلاح:** `gateway-forwarder` لا يحتاج نفس التعديل - هو من يُنشئ `legacy-forwarder` أصلاً، ولا علاقة له بـ`core-ingest` (التي هي حصراً استعداد لمستهلك P1 مستقبلي يعيش خارج هذه العملية).'
DEVIATIONS_ANCHOR='والتحقق النهائي بـ`docker compose config` الحقيقي.'

append_guarded "docs/P0_FINDINGS.md" "$FINDINGS_ANCHOR" "$FINDINGS_NEW_B64" "docs/P0_FINDINGS.md (F19/F20/F21)" || true
append_guarded "docs/P0_DEVIATIONS.md" "$DEVIATIONS_ANCHOR" "$DEVIATIONS_NEW_B64" "docs/P0_DEVIATIONS.md (D-29/D-30/D-31)" || true

echo
cat <<'EOF'
================================================================================
Batch B delivered: gateway/ engine-metadata + reconnect-route fixes, core/'s
P0.7 channel-lifecycle routes (full tree, supersedes Batch A), and the
F19-F21/D-29-D-31 documentation entries (or a clear abort + saved section if
your real docs files had diverged from this sandbox's copy - check for any
"error:" lines above).

Nothing has been committed. Next steps:

  1) Review the diff:
       git status
       git diff --stat -- gateway/ core/ docs/
       git add -N core/ gateway/ docs/ && git diff -- core/ gateway/ docs/

  2) Re-run the gateway suite for real, against your own infra:
       cd gateway
       npm test
     Expect 140/140 (4 heavy + 136 other, see scripts/run-tests.mjs's own
     two-phase split). hunt_gate should stay clean on every file this batch
     touched (see the file list embedded above in this script).

  3) core/'s own venv should already exist from Batch A. Re-run its suite:
       cd core
       .venv/bin/python -m pytest tests/ -v
       .venv/bin/ruff check .
       .venv/bin/lint-imports
       .venv/bin/mypy app/
     Expect 265/265 passed, all three lint/type/import checks clean.

  4) Only after both suites are green for real on your infra: git commit
     (Gate A - your explicit, separate step, never this script's).

Still blocked on you for the NEXT piece (docker-compose `api` service +
.env.example wiring): I still don't have the real, current content of
ops/pgbouncer.ini and ops/postgres/init/10_roles.sh. Please run
gather_p07b2_context.sh (NOT gather_p07b_context.sh - that's the old one)
and paste its full output back. Everything in THIS batch (gateway + core
channel routes + docs) does not depend on that and is safe to apply now.
================================================================================
EOF
